bitflags :: bitflags ! { # [doc = " Rustier interface for [`SCNetworkReachabilityFlags`]."] # [doc = ""] # [doc = " [`SCNetworkReachability`]: https://developer.apple.com/documentation/systemconfiguration/scnetworkreachabilityflags"] # [derive (Debug , Clone , Copy , PartialEq , Eq , Hash)] pub struct ReachabilityFlags : u32 { # [doc = " The specified node name or address can be reached via a transient connection, such as"] # [doc = " PPP."] const TRANSIENT_CONNECTION = kSCNetworkReachabilityFlagsTransientConnection ; # [doc = " The specified node name or address can be reached using the current network"] # [doc = " configuration."] const REACHABLE = kSCNetworkReachabilityFlagsReachable ; # [doc = " The specified node name or address can be reached using the current network"] # [doc = " configuration, but a connection must first be established. If this flag is set, the"] # [doc = " `CONNECTION_ON_TRAFFIC` flag, `CONNECTION_ON_DEMAND` flag, or `IS_WANN` flag is also"] # [doc = " typically set to indicate the type of connection required. If the user must manually"] # [doc = " make the connection, the `INTERVENTION_REQUIRED` flag is also set."] const CONNECTION_REQUIRED = kSCNetworkReachabilityFlagsConnectionRequired ; # [doc = " The specified node name or address can be reached using the current network"] # [doc = " configuration, but a connection must first be established. Any traffic directed to the"] # [doc = " specified name or address will initiate the connection."] const CONNECTION_ON_TRAFFIC = kSCNetworkReachabilityFlagsConnectionOnTraffic ; # [doc = " The specified node name or address can be reached using the current network"] # [doc = " configuration, but a connection must first be established."] const INTERVENTION_REQUIRED = kSCNetworkReachabilityFlagsInterventionRequired ; # [doc = " The specified node name or address can be reached using the current network"] # [doc = " configuration, but a connection must first be established."] const CONNECTION_ON_DEMAND = kSCNetworkReachabilityFlagsConnectionOnDemand ; # [doc = " The specified node name or address is one that is associated with a network interface on the current system."] const IS_LOCAL_ADDRESS = kSCNetworkReachabilityFlagsIsLocalAddress ; # [doc = " Network traffic to the specified node name or address will not go through a gateway, but"] # [doc = " is routed directly to one of the interfaces in the system."] const IS_DIRECT = kSCNetworkReachabilityFlagsIsDirect ; # [doc = " The specified node name or address can be reached via a cellular connection, such as EDGE or GPRS."] const IS_WWAN = kSCNetworkReachabilityFlagsIsWWAN ; } }